package com.example.hilolive;
import android.app.*;import android.content.*;import android.graphics.*;import android.hardware.display.*;import android.media.*;import android.media.projection.*;import android.os.*;import android.view.*;import android.widget.TextView;import android.provider.Settings;import com.google.mlkit.vision.common.InputImage;import com.google.mlkit.vision.text.*;import com.google.mlkit.vision.text.latin.TextRecognizerOptions;import java.nio.ByteBuffer;import java.util.*;import java.util.regex.*;
public class CaptureService extends Service {
 private MediaProjection projection;private VirtualDisplay display;private ImageReader reader;private TextRecognizer recognizer;private Handler handler;private WindowManager wm;private TextView overlay;private int x=30,y=25,w=40,h=30;private boolean busy=false;private String last="";private int consecutive=0;private int screenW,screenH;
 @Override public IBinder onBind(Intent i){return null;}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent==null)return START_NOT_STICKY;String action=intent.getAction();if("CROP".equals(action)){setCrop(intent);return START_STICKY;}if(!"START".equals(action))return START_NOT_STICKY;setCrop(intent);createNotification();MediaProjectionManager manager=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);Intent token;if(Build.VERSION.SDK_INT>=33)token=intent.getParcelableExtra("data",Intent.class);else token=intent.getParcelableExtra("data");if(token==null){stopSelf();return START_NOT_STICKY;}
 projection=manager.getMediaProjection(intent.getIntExtra("result",Activity.RESULT_CANCELED),token);projection.registerCallback(new MediaProjection.Callback(){@Override public void onStop(){stopSelf();}},new Handler(Looper.getMainLooper()));recognizer=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);handler=new Handler(Looper.getMainLooper());wm=(WindowManager)getSystemService(WINDOW_SERVICE);DisplayMetricsCompat metrics=new DisplayMetricsCompat(this);screenW=metrics.width;screenH=metrics.height;reader=ImageReader.newInstance(screenW,screenH,android.graphics.PixelFormat.RGBA_8888,2);display=projection.createVirtualDisplay("HiLoCapture",screenW,screenH,metrics.density,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,handler);showOverlay();handler.post(scan);return START_STICKY;}
 private void setCrop(Intent i){x=i.getIntExtra("x",x);y=i.getIntExtra("y",y);w=i.getIntExtra("w",w);h=i.getIntExtra("h",h);}
 private void createNotification(){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("capture","Screen analysis",NotificationManager.IMPORTANCE_LOW));Intent open=new Intent(this,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(this,0,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification n=new Notification.Builder(this,"capture").setContentTitle("HiLo analysis active").setContentText("Screen is being read locally. Tap to adjust.").setSmallIcon(android.R.drawable.ic_menu_view).setContentIntent(pi).setOngoing(true).build();if(Build.VERSION.SDK_INT>=29)startForeground(1,n,android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION);else startForeground(1,n);}
 private void showOverlay(){if(!Settings.canDrawOverlays(this))return;overlay=new TextView(this);overlay.setText("HiLo OCR starting...");overlay.setTextColor(Color.WHITE);overlay.setTextSize(13);overlay.setPadding(14,10,14,10);overlay.setBackgroundColor(0xD9222936);WindowManager.LayoutParams p=new WindowManager.LayoutParams(-2,-2,Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE,android.graphics.PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.START;p.x=12;p.y=110;wm.addView(overlay,p);}
 private final Runnable scan=new Runnable(){public void run(){if(reader==null)return;if(!busy){Image image=reader.acquireLatestImage();if(image!=null){busy=true;Bitmap bitmap=null;try{Image.Plane plane=image.getPlanes()[0];ByteBuffer buffer=plane.getBuffer();int stride=plane.getRowStride(),pixel=plane.getPixelStride();Bitmap full=Bitmap.createBitmap(screenW+(stride-pixel*screenW)/pixel,screenH,Bitmap.Config.ARGB_8888);full.copyPixelsFromBuffer(buffer);int left=Math.min(full.getWidth()-1,Math.max(0,full.getWidth()*x/100));int top=Math.min(full.getHeight()-1,Math.max(0,full.getHeight()*y/100));int cw=Math.max(1,Math.min(full.getWidth()-left,full.getWidth()*Math.max(1,w)/100));int ch=Math.max(1,Math.min(full.getHeight()-top,full.getHeight()*Math.max(1,h)/100));bitmap=Bitmap.createBitmap(full,left,top,cw,ch);full.recycle();}catch(Exception ex){busy=false;}finally{image.close();}if(bitmap!=null){Bitmap cropped=bitmap;recognizer.process(InputImage.fromBitmap(cropped,0)).addOnSuccessListener(t->{String raw=t.getText();String rank=extractRank(raw);if(rank!=null){if(rank.equals(last))consecutive++;else{last=rank;consecutive=1;}if(consecutive>=2){Intent u=new Intent("com.example.hilolive.UPDATE");u.setPackage(getPackageName());u.putExtra("card",rank);u.putExtra("ocr",raw);sendBroadcast(u);if(overlay!=null)overlay.setText("Card "+rank+" | Higher "+String.format(Locale.US,"%.1f%%",100*Engine.probability(Engine.rank(rank),true))+" | Lower "+String.format(Locale.US,"%.1f%%",100*Engine.probability(Engine.rank(rank),false)));}}else if(overlay!=null)overlay.setText("OCR: card unclear — adjust crop");}).addOnCompleteListener(t->{cropped.recycle();busy=false;});}else busy=false;}}handler.postDelayed(this,1100);}};
 private String extractRank(String raw){if(raw==null)return null;String[] lines=raw.toUpperCase(Locale.US).split("\\R");for(String line:lines){String normalized=line.trim().replaceAll("[^A-Z0-9]","");if(Engine.rank(normalized)>=0)return normalized;}return null;}
 @Override public void onDestroy(){if(handler!=null)handler.removeCallbacksAndMessages(null);if(display!=null)display.release();if(reader!=null)reader.close();if(projection!=null)projection.stop();if(recognizer!=null)recognizer.close();if(overlay!=null&&wm!=null)wm.removeView(overlay);super.onDestroy();}
 private static class DisplayMetricsCompat {int width,height,density;DisplayMetricsCompat(Context c){android.util.DisplayMetrics m=c.getResources().getDisplayMetrics();width=m.widthPixels;height=m.heightPixels;density=m.densityDpi;}}
}
